// Language toggle functionality with fade transitions and localStorage
    (function() {
      const container = document.querySelector('.bilingual-container');
      const toggle = document.querySelector('.language-toggle');
      const htmlElement = document.documentElement;

      // Get initial language from localStorage, URL hash, or default to Spanish
      const getInitialLang = () => {
        // First check localStorage
        const storedLang = localStorage.getItem('preferredLang');
        if (storedLang === 'es' || storedLang === 'en') {
          return storedLang;
        }

        // Then check URL hash
        const hash = window.location.hash;
        if (hash === '#lang=en') return 'en';
        if (hash === '#lang=es') return 'es';

        // Default to Spanish
        return 'es';
      };

      let currentLang = getInitialLang();

      // Set initial language with fade-in
      const setLanguage = (lang) => {
        const activeContent = lang === 'es' ? '.content-es' : '.content-en';
        const inactiveContent = lang === 'es' ? '.content-en' : '.content-es';

        // Add fade-in to active language
        document.querySelector(activeContent).classList.add('fade-in');

        container.setAttribute('data-lang', lang);
        htmlElement.setAttribute('lang', lang);
        htmlElement.setAttribute('data-lang', lang);
        window.location.hash = `lang=${lang}`;
        localStorage.setItem('preferredLang', lang);

        // Remove fade-in class after animation
        setTimeout(() => {
          document.querySelector(activeContent).classList.remove('fade-in');
        }, 300);
      };

      // Set initial language
      setLanguage(currentLang);

      // Toggle function with smooth transition
      toggle.addEventListener('click', () => {
        currentLang = currentLang === 'es' ? 'en' : 'es';
        setLanguage(currentLang);
      });

      // Handle back/forward browser navigation
      window.addEventListener('hashchange', () => {
        const newLang = getInitialLang();
        if (newLang !== currentLang) {
          currentLang = newLang;
          setLanguage(currentLang);
        }
      });
    })();

    // WebMCP Tool Definitions
    window.mcpTools = {
      'toggle-language': {
        name: 'toggle-language',
        description: 'Switch between Spanish and English language versions',
        inputSchema: {
          type: 'object',
          properties: {
            lang: {
              type: 'string',
              enum: ['es', 'en'],
              description: 'Target language code'
            }
          },
          required: ['lang']
        },
        execute: async (params) => {
          const { lang } = params;
          const container = document.querySelector('.bilingual-container');
          const htmlElement = document.documentElement;
          container.setAttribute('data-lang', lang);
          htmlElement.setAttribute('lang', lang);
          htmlElement.setAttribute('data-lang', lang);
          window.location.hash = `lang=${lang}`;
          localStorage.setItem('preferredLang', lang);
          return { success: true, currentLang: lang };
        }
      },
      'menu-query': {
        name: 'menu-query',
        description: 'Query menu items by category or search term',
        inputSchema: {
          type: 'object',
          properties: {
            category: {
              type: 'string',
              enum: ['fish', 'paella', 'salads', 'gazpacho'],
              description: 'Menu category to query'
            },
            search: {
              type: 'string',
              description: 'Search term for menu items'
            }
          }
        },
        execute: async (params) => {
          // Extract menu data from DOM
          const menuItems = Array.from(document.querySelectorAll('.menu-item')).map(item => ({
            name: item.querySelector('.menu-item-name').textContent,
            price: item.querySelector('.menu-item-price').textContent,
            description: item.querySelector('.menu-item-description').textContent,
            specialty: item.classList.contains('specialty')
          }));
          return { success: true, items: menuItems };
        }
      },
      'reservation-info': {
        name: 'reservation-info',
        description: 'Get restaurant contact and reservation information',
        inputSchema: {
          type: 'object',
          properties: {}
        },
        execute: async () => {
          return {
            success: true,
            info: {
              phone: '+34 952 XXX XXX',
              email: 'reservas@losgranainos.es',
              hours: '12:00-16:00 and 19:00-23:30 (Daily)',
              address: 'Paseo Marítimo de la Cala, 29649 Cala de Mijas, Málaga, Spain',
              coordinates: { lat: 36.5167, lng: -4.6333 }
            }
          };
        }
      },
      'location-info': {
        name: 'location-info',
        description: 'Get geographic location and directions information',
        inputSchema: {
          type: 'object',
          properties: {}
        },
        execute: async () => {
          return {
            success: true,
            location: {
              address: 'Paseo Marítimo de la Cala, 29649 Cala de Mijas, Málaga, Spain',
              coordinates: { lat: 36.5167, lng: -4.6333 },
              region: 'Andalusia',
              nearbyLandmarks: ['Cala de Mijas Beach', 'Costa del Sol', 'Málaga City']
            }
          };
        }
      },
      'show-map': {
        name: 'show-map',
        description: 'Navigate to interactive map and show contact info popup',
        inputSchema: {
          type: 'object',
          properties: {}
        },
        execute: async () => {
          // Scroll to contact section
          const contactSection = document.querySelector('#contacto-es, #contact-en');
          if (contactSection) {
            contactSection.scrollIntoView({ behavior: 'smooth', block: 'start' });

            // Open the map popup after scrolling
            setTimeout(() => {
              const currentLang = document.querySelector('.bilingual-container').getAttribute('data-lang');
              const marker = currentLang === 'es' ? window.mapMarkerES : window.mapMarkerEN;
              if (marker) {
                marker.openPopup();
              }
            }, 1000);

            return { success: true, action: 'navigated to map and opened contact popup' };
          }
          return { success: false, error: 'contact section not found' };
        }
      }
    };

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });
    });

// Initialize maps for both languages
    (function() {
      // Restaurant coordinates
      const restaurantCoords = [36.5167, -4.6333];

      // Contact information for popup (Spanish)
      const contactInfoES = `
        <div class="map-popup-title">Los Granainos</div>
        <div class="map-popup-info">
          <div class="map-popup-item">
            <span class="map-popup-icon">📍</span>
            <span>Paseo Marítimo de la Cala<br>29649 Cala de Mijas<br>Málaga, España</span>
          </div>
          <div class="map-popup-item">
            <span class="map-popup-icon">🕐</span>
            <span>Lunes - Domingo<br>12:00 - 16:00 | 19:00 - 23:30</span>
          </div>
          <div class="map-popup-item">
            <span class="map-popup-icon">📞</span>
            <span>+34 952 XXX XXX<br>reservas@losgranainos.es</span>
          </div>
        </div>
      `;

      // Contact information for popup (English)
      const contactInfoEN = `
        <div class="map-popup-title">Los Granainos</div>
        <div class="map-popup-info">
          <div class="map-popup-item">
            <span class="map-popup-icon">📍</span>
            <span>Paseo Marítimo de la Cala<br>29649 Cala de Mijas<br>Málaga, Spain</span>
          </div>
          <div class="map-popup-item">
            <span class="map-popup-icon">🕐</span>
            <span>Monday - Sunday<br>12:00 - 16:00 | 19:00 - 23:30</span>
          </div>
          <div class="map-popup-item">
            <span class="map-popup-icon">📞</span>
            <span>+34 952 XXX XXX<br>reservas@losgranainos.es</span>
          </div>
        </div>
      `;

      // Initialize Spanish map
      const mapES = L.map('map-es', {
        center: restaurantCoords,
        zoom: 15,
        scrollWheelZoom: false
      });

      // Add OpenStreetMap tiles (Spanish)
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
        maxZoom: 19
      }).addTo(mapES);

      // Add marker with popup (Spanish)
      const markerES = L.marker(restaurantCoords).addTo(mapES);
      markerES.bindPopup(contactInfoES, { maxWidth: 300 });
      window.mapMarkerES = markerES; // Make accessible for WebMCP tools

      // Initialize English map
      const mapEN = L.map('map-en', {
        center: restaurantCoords,
        zoom: 15,
        scrollWheelZoom: false
      });

      // Add OpenStreetMap tiles (English)
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
        maxZoom: 19
      }).addTo(mapEN);

      // Add marker with popup (English)
      const markerEN = L.marker(restaurantCoords).addTo(mapEN);
      markerEN.bindPopup(contactInfoEN, { maxWidth: 300 });
      window.mapMarkerEN = markerEN; // Make accessible for WebMCP tools

      // Open popup on hover (Spanish)
      markerES.on('mouseover', function() {
        this.openPopup();
      });

      // Open popup on hover (English)
      markerEN.on('mouseover', function() {
        this.openPopup();
      });

      // Invalidate map size when language changes (ensures proper rendering)
      const observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(mutation) {
          if (mutation.attributeName === 'data-lang') {
            setTimeout(function() {
              mapES.invalidateSize();
              mapEN.invalidateSize();
            }, 100);
          }
        });
      });

      observer.observe(document.querySelector('.bilingual-container'), {
        attributes: true,
        attributeFilter: ['data-lang']
      });
    })();
